#include <WiFi.h>
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>
#include <DHT.h>
#include <ESP32Servo.h>

// --- Cấu hình chân phần cứng ---
#define DHTPIN          14
#define DHTTYPE         DHT11
DHT dht(DHTPIN, DHTTYPE);

#define PIR_PIN         13

// Màn hình màu ST7789 (SPI) - Chân MISO đặt -1 để nhường GPIO 13 cho PIR
#define TFT_CS          -1  
#define TFT_DC          9
#define TFT_RST         10
Adafruit_ST7789 tft = Adafruit_ST7789(TFT_CS, TFT_DC, TFT_RST);

// Động cơ Servo Pan-Tilt
Servo servoX;
Servo servoY;
#define SERVO_X_PIN     41
#define SERVO_Y_PIN     42

// Cấu hình Wi-Fi Access Point
const char* ssid = "ESP32-S3-Robot";
const char* password = "12345678";
WiFiServer server(80);

// Biến lưu trữ trạng thái hệ thống
float currentTemp = 0.0;
float currentHumidity = 0.0;
int motionState = 0;
unsigned long previousMillis = 0;
const long interval = 2000; // Cập nhật cảm biến mỗi 2 giây

// Hàm vẽ biểu cảm khuôn mặt lên màn hình ST7789
void drawFace(String emotion) {
  tft.fillScreen(0x0000); // Xóa màn hình (Màu đen)

  if (emotion == "normal") {
    // Mắt xanh bình thường
    tft.fillCircle(70, 90, 16, 0x07E0); 
    tft.fillCircle(170, 90, 16, 0x07E0);
    // Miệng cười
    tft.fillRect(90, 150, 60, 8, 0x07E0); 
  } else if (emotion == "motion") {
    // Mắt đỏ cảnh báo chuyển động
    tft.fillCircle(70, 90, 20, 0xF800); 
    tft.fillCircle(170, 90, 20, 0xF800);
    // Miệng ngạc nhiên
    tft.fillCircle(120, 155, 14, 0xF800); 
  }

  // Hiển thị trạng thái bằng chữ
  tft.setCursor(60, 205);
  tft.setTextColor(0xFFFF); // Chữ màu trắng
  tft.setTextSize(2);
  tft.print(emotion);
}

void setup() {
  Serial.begin(115200);
  delay(500);

  dht.begin();
  pinMode(PIR_PIN, INPUT);

  // Khởi động giao tiếp SPI (Đặt MISO = -1 để giải phóng chân 13)
  SPI.begin(12, -1, 11, -1);
  tft.init(240, 240);
  tft.setRotation(2);
  drawFace("normal");

  // Khởi động Động cơ Servo qua thư viện ESP32Servo
  ESP32PWM::allocateTimer(0);
  ESP32PWM::allocateTimer(1);
  servoX.setPeriodHertz(50);
  servoY.setPeriodHertz(50);
  servoX.attach(SERVO_X_PIN, 500, 2400);
  servoY.attach(SERVO_Y_PIN, 500, 2400);

  servoX.write(90);
  servoY.write(90);

  // Khởi động mạng Wi-Fi nội bộ cho Robot phát sóng
  WiFi.softAP(ssid, password);
  server.begin();
}

void loop() {
  unsigned long currentMillis = millis();

  // Đọc cảm biến định kỳ mỗi 2 giây
  if (currentMillis - previousMillis >= interval) {
    previousMillis = currentMillis;
    currentTemp = dht.readTemperature();
    currentHumidity = dht.readHumidity();
  }

  // Đọc trạng thái cảm biến chuyển động PIR
  motionState = digitalRead(PIR_PIN);

  // Xử lý phản ứng phần cứng khi phát hiện chuyển động
  if (motionState == HIGH) {
    drawFace("motion");
    servoX.write(45);
    delay(200);
    servoX.write(135);
    delay(200);
    servoX.write(90);
  } else {
    drawFace("normal");
  }

  // Xử lý kết nối Web Server từ điện thoại
  WiFiClient client = server.available();
  if (client) {
    String currentLine = "";
    while (client.connected()) {
      if (client.available()) {
        char c = client.read();
        if (c == '\n') {
          if (currentLine.length() == 0) {
            // Gom toàn bộ phản hồi HTTP vào một chuỗi duy nhất
            String html = "HTTP/1.1 200 OK\r\n";
            html += "Content-Type: text/html; charset=utf-8\r\n";
            html += "Connection: close\r\n\r\n";

            html += "<!DOCTYPE HTML>\n";
            html += "<html><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width, initial-scale=1'>\n";
            html += "<title>ESP32-S3 Robot Dashboard</title>\n";
            html += "<style>body{font-family:Arial;text-align:center;background:#f4f4f9;padding:20px;}\n";
            html += ".card{background:white;padding:20px;border-radius:10px;box-shadow:0 4px 8px rgba(0,0,0,0.1);display:inline-block;margin-top:20px;}\n";
            html += "h2{color:#333;}.val{font-size:24px;font-weight:bold;color:#007BFF;}</style></head>\n";
            html += "<body>\n";
            html += "<h2>ESP32-S3 AI Robot Control Panel</h2>\n";
            html += "<div class='card'>\n";

            html += "<p><b>Temperature:</b> <span class='val'>";
            html += String(isnan(currentTemp) ? 0 : currentTemp);
            html += " C</span></p>\n";

            html += "<p><b>Humidity:</b> <span class='val'>";
            html += String(isnan(currentHumidity) ? 0 : currentHumidity);
            html += " %</span></p>\n";

            if (motionState == HIGH) {
              html += "<p><b>PIR Status:</b> <span style='color:red;font-size:20px;font-weight:bold;'>Motion Detected!</span></p>\n";
            } else {
              html += "<p><b>PIR Status:</b> <span style='color:green;font-size:20px;font-weight:bold;'>Safe</span></p>\n";
            }

            html += "</div></body></html>\n";

    // Sử dụng client.write() để truyền dữ liệu an toàn tuyệt đối
    client.write((const uint8_t*)html.c_str(), html.length());
            break;
          } else {
            currentLine = "";
          }
        } else if (c != '\r') {
          currentLine += c;
        }
      }
    }
    delay(10);
    client.stop();
  }

  delay(100);
}
